/* ---- Progression composite ---- */
function targets(){return{stages:12,recherche:24,publications:3,passerelle:24,formations:1}}
function score(){const t=targets();const compAvg=D.comp.reduce((a,b)=>a+b,0)/(D.comp.length*5);
const pubDone=L('publications').filter(x=>x.statut=='Publié / présenté'||x.statut=='Accepté').length;
const formDone=L('formations').filter(x=>(x.st=='Terminée'||x.st=='Validée')).length;
const parts=[
['Stages',Math.min(1,L('stages').length/t.stages)],
['Recherche',Math.min(1,L('recherche').length/t.recherche)],
['Publications',Math.min(1,pubDone/t.publications)],
['Dossier passerelle',passScore()],
['Compétences',compAvg],
['Formations',Math.min(1,formDone/t.formations)]
];
const avg=parts.reduce((a,p)=>a+p[1],0)/parts.length;
return{avg,parts}}
function gauge(pct,big){const c=pct>=.66?'#2e8b57':pct>=.33?'#d08a1a':'#c0392b';return `<div class="${big?'traj':'bar'}" style="${big?`background:${c}`:''}">${big?Math.round(pct*100)+' % — progression globale du dossier':''}${big?'':`<i style="width:${Math.round(pct*100)}%;background:${c}"></i>`}</div>`}

/* ---- Stats & accueil ---- */
const ACC=['Courant','Livret / épargne','Investissement','Espèces','Autre'];
function fin(){D.fin=D.fin||{};D.fin.open=D.fin.open||{};D.fin.budget=D.fin.budget||{};return D.fin}
function accounts(){const f=fin(),acc={};ACC.forEach(x=>acc[x]=+f.open[x]||0);L('finance').forEach(x=>{const m=+x.mt||0,c=ACC.includes(x.compte)?x.compte:'Courant';
if(x.type=='Revenu')acc[c]+=m;else if(x.type=='Dépense'||x.type=='Formation/compétences')acc[c]-=m;else if(x.type=='Transfert → épargne'||x.type=='Épargne'){acc.Courant-=m;acc['Livret / épargne']+=m}else if(x.type=='Transfert épargne → courant'){acc['Livret / épargne']-=m;acc.Courant+=m}else if(x.type=='Transfert → investissement'||x.type=='Investissement'){acc.Courant-=m;acc.Investissement+=m}else if(x.type=='Transfert investissement → courant'){acc.Investissement-=m;acc.Courant+=m}else if(x.type=='Transfert interne'&&c!='Courant'){acc.Courant-=m;acc[c]+=m}});return acc}
function finMonths(){const m={};L('finance').forEach(x=>{if(!x.date)return;const k=x.date.slice(0,7);m[k]=m[k]||{rev:0,dep:0};const v=+x.mt||0;if(x.type=='Revenu')m[k].rev+=v;else if(x.type=='Dépense'||x.type=='Formation/compétences')m[k].dep+=v});return m}
function stats(){
const w=d=>d>=add(td(),-6);const sa=L('sante').filter(x=>w(x.date));const som=sa.filter(x=>x.som);const sleep=som.length?som.reduce((a,x)=>a+ +x.som,0)/som.length:null;
const sport=sa.filter(x=>x.sport&&x.sport!='Aucun').length;const rech=L('recherche').filter(x=>x.date&&w(x.date)).length;
const fl=L('finance'),sum=ts=>fl.filter(x=>ts.includes(x.type)).reduce((t,x)=>t+(+x.mt||0),0);
const rev=sum(['Revenu']),dep=sum(['Dépense']),formCost=sum(['Formation/compétences']),epargneInvest=Math.max(0,sum(['Transfert → épargne','Épargne','Transfert → investissement','Investissement'])-sum(['Transfert épargne → courant','Transfert investissement → courant']));
const acc=accounts(),liq=Math.round((acc.Courant+acc['Espèces'])*100)/100,ep=Math.round(acc['Livret / épargne']*100)/100,inv=Math.round(acc.Investissement*100)/100,pat=Math.round(ACC.reduce((t,x)=>t+acc[x],0)*100)/100;
let streak=0;const ds=new Set(L('sante').map(x=>x.date));for(let i=0;ds.has(add(td(),-i));i++)streak++;
return{sleep,sport,rech,rev,dep,formCost,epargneInvest,solde:liq,liq,ep,inv,pat,acc,streak}}
function finSet(g,k,v){const f=fin();f[g]=f[g]||{};f[g][k]=v===''?'':+v;save();render()}
function finVal(k,v){fin()[k]=v===''?'':+v;save();render()}
function finX(){const s=stats(),f=fin(),mo=finMonths(),ks=Object.keys(mo).sort().slice(-6),cur=td().slice(0,7);
const last3=Object.keys(mo).sort().slice(-3),avgDep=last3.length?last3.reduce((t,k)=>t+mo[k].dep,0)/last3.length:0,avgNet=last3.length?last3.reduce((t,k)=>t+mo[k].rev-mo[k].dep,0)/last3.length:0;
const months=+f.fondsMois||3,target=Math.round(avgDep*months),fp=target?Math.min(1,s.ep/target):0;
const spent={};L('finance').filter(x=>x.type=='Dépense'&&(x.date||'').slice(0,7)==cur).forEach(x=>{const c=x.cat||'Autre';spent[c]=(spent[c]||0)+(+x.mt||0)});
const cats=['Logement','Alimentation','Transport','Santé','Études','Abonnements','Loisirs','Formation','Autre'];
const mx=Math.max(100,...ks.map(k=>Math.max(mo[k].rev,mo[k].dep))),bw=300/Math.max(ks.length,1);
const bars=ks.map((k,i)=>`<rect x="${i*bw+4}" y="${70-mo[k].rev/mx*58}" width="${bw/2-5}" height="${mo[k].rev/mx*58}" fill="#2e8b57"/><rect x="${i*bw+bw/2}" y="${70-mo[k].dep/mx*58}" width="${bw/2-5}" height="${mo[k].dep/mx*58}" fill="#c0392b"/><text x="${i*bw+bw/2}" y="82" font-size="8" text-anchor="middle">${k.slice(2)}</text>`).join('');
let cum=ACC.reduce((t,x)=>t+(+f.open[x]||0),0);const pts=Object.keys(mo).sort().map(k=>{cum+=mo[k].rev-mo[k].dep;return cum});
const pmx=Math.max(1,...pts.map(Math.abs)),line=pts.length>1?`<svg viewBox="0 0 300 70" width="100%"><polyline fill="none" stroke="var(--a)" stroke-width="2" points="${pts.map((v,i)=>(10+i*(280/(pts.length-1)))+','+(35-v/pmx*28)).join(' ')}"/></svg>`:'<p class="m">Pas assez de mois pour tracer l\'évolution du patrimoine.</p>';
const bar=(v,t)=>t>0?gauge(Math.min(1,v/t)):'';
return `<div class="card" style="text-align:center"><span class="m">Liquidités (compte courant + espèces)</span><div style="font-size:32px;font-weight:700;color:${s.liq>=0?'var(--g)':'var(--r)'}">${s.liq} €</div><span class="m">Patrimoine total : ${s.pat} €</span></div>
<div class="grid"><div class="k"><b>${s.ep} €</b><span>épargne</span></div><div class="k"><b>${s.inv} €</b><span>investissements</span></div><div class="k"><b>${s.rev} €</b><span>revenus cumulés</span></div><div class="k"><b>${s.dep} €</b><span>dépenses cumulées</span></div><div class="k"><b>${s.formCost} €</b><span>formations/compétences</span></div><div class="k"><b>${Math.round(avgNet)} €</b><span>solde net moyen / mois (3 mois)</span></div></div>
<p class="m">Les transferts vers l'épargne ou les investissements ne sont ni des revenus ni des dépenses : ils déplacent l'argent d'un compte à l'autre (ancien type « Épargne » = transfert). Un retrait « Transfert épargne → courant » remet l'argent sur le compte courant sans être un revenu.</p>
<div class="card"><h3>Soldes d'ouverture des comptes</h3><p class="m">Montant présent sur chaque compte avant ta première saisie.</p><div class="grid">${ACC.map(x=>`<div><label>${x}</label><input type="number" value="${f.open[x]??''}" onchange="finSet('open','${x}',this.value)"></div>`).join('')}</div></div>
<div class="card"><h3>Fonds de sécurité</h3><div class="row"><span class="m">Cible : <input type="number" min="1" max="12" style="width:70px" value="${months}" onchange="finVal('fondsMois',this.value)"> mois de dépenses = ${target} €</span><span class="m">Épargne : ${s.ep} €</span></div>${bar(s.ep,target)}</div>
<div class="card"><h3>Objectifs</h3><div class="grid"><div><label>Objectif d'épargne (€)</label><input type="number" value="${f.objEp??''}" onchange="finVal('objEp',this.value)">${bar(s.ep,+f.objEp)}</div><div><label>Objectif d'investissement (€)</label><input type="number" value="${f.objInv??''}" onchange="finVal('objInv',this.value)">${bar(s.inv,+f.objInv)}</div></div></div>
<div class="card"><h3>Budget mensuel · ${cur}</h3>${cats.map(c=>{const b=+f.budget[c]||0,d=spent[c]||0;return `<div class="row"><span>${c} <span class="m">${d} € dépensés</span></span><input type="number" style="width:90px" placeholder="budget" value="${f.budget[c]??''}" onchange="finSet('budget','${c}',this.value)"></div>${b?`<div class="bar"><i style="width:${Math.min(100,d/b*100)}%;background:${d>b?'var(--r)':'var(--g)'}"></i></div>`:''}`}).join('')}</div>
<div class="card"><h3>Revenus (vert) et dépenses (rouge) · 6 mois</h3><svg viewBox="0 0 300 86" width="100%">${bars}</svg></div>
<div class="card"><h3>Évolution du patrimoine & projection</h3>${line}<p class="m">Projection à 12 mois (au rythme net moyen des 3 derniers mois) : <b>${Math.round(s.pat+avgNet*12)} €</b>. Estimation indicative, non garantie.</p></div>`}
function period(){const d=td();if(d<'2026-09-07')return['Avant la rentrée','IFSI 1 en septembre 2026'];if(d<'2027-09-01')return['IFSI 1 · 2026-2027','Excellence, méthodes M1-M5, stages, sport, sommeil'];if(d<'2028-09-01')return['IFSI 2 · 2027-2028','Différenciation : stages stratégiques, premiers projets de recherche'];if(d<'2029-09-01')return['IFSI 3 · 2028-2029','Dossier passerelle : notes, stages, mémoire, oral'];return['Après le DEI','Passerelle, spécialisation ou emploi IDE : options ouvertes']}
function timeline(){const W=320,x=y=>(y-2026)/10*W,now=new Date(),cy=now.getFullYear()+(now.getMonth()+now.getDate()/31)/12,seg=[[2026.7,2027.7,'IFSI 1','#1F4D3A'],[2027.7,2028.7,'IFSI 2','#2c6b52'],[2028.7,2029.7,'IFSI 3','#3f8a6c'],[2029.7,2036,'Passerelle · spécialisation · recherche (selon les données)','#C9A24B']];
return `<svg viewBox="0 0 ${W} 74" width="100%">${seg.map(([s,e,l,c])=>`<rect x="${x(s)}" y="22" width="${x(e)-x(s)-2}" height="22" rx="6" fill="${c}"/><text x="${x(s)+5}" y="37" font-size="8.5" style="fill:#fff">${e-s>1.5?'DEI → '+(e>2035?'médecine ? → recherche':''):l}</text>`).join('')}${[2026,2028,2030,2032,2034,2036].map(y=>`<text x="${x(y)}" y="60" font-size="8.5" text-anchor="middle">${y}</text><line x1="${x(y)}" x2="${x(y)}" y1="46" y2="50" stroke="currentColor" opacity=".4"/>`).join('')}<line x1="${x(Math.min(2036,Math.max(2026,cy)))}" x2="${x(Math.min(2036,Math.max(2026,cy)))}" y1="12" y2="48" stroke="#E8745A" stroke-width="2"/><text x="${x(Math.min(2036,Math.max(2026,cy)))}" y="9" font-size="8.5" text-anchor="middle" style="fill:#E8745A">aujourd'hui</text></svg>`}
function deadlines(){const t=td(),o=[];pchk().forEach(c=>{if(c.st!='Fait'&&c.due)o.push({d:c.due,l:c.t,tab:'passerelle',late:c.due<t})});L('stages').forEach(s=>{if(s.debut&&s.debut>=t)o.push({d:s.debut,l:'Début de stage : '+s.lieu,tab:'stages'})});gl('pcal').forEach(c=>{if(c.d&&c.st!='Fait'&&c.d>=t)o.push({d:c.d,l:c.t||'Étape officielle',tab:'passerelle'})});L('projets').forEach(x=>{if(x.ech&&x.ech>=t&&x.st!='Terminé')o.push({d:x.ech,l:'Projet : '+x.titre,tab:'projets'})});L('reseau').forEach(x=>{if(x.suivi&&x.suivi>=t)o.push({d:x.suivi,l:'Relancer '+x.nom,tab:'reseau'})});return o.sort((p,q)=>p.d<q.d?-1:1).slice(0,5)}
function actions(){const a=[],t=td(),ck=pchk(),late=ck.filter(c=>c.st!='Fait'&&c.due&&c.due<t);
if(late.length)a.push(['Rattraper '+late.length+' échéance(s) du dossier passerelle','passerelle']);
const ax=AX.map(x=>({x,w:L('passerelle').filter(p=>p.axe==x).reduce((s,p)=>s+fw(p),0)})).sort((p,q)=>p.w-q.w)[0];if(ax&&ax.w<6)a.push(['Documenter l\'axe « '+ax.x.slice(2)+' » (poids '+ax.w+'/6)','passerelle']);
if(notesData().a.some(x=>+x.note<10))a.push(['Consolider les UE sous 10/20','notes']);
if(!L('sante').some(x=>x.date>=add(t,-2)))a.push(['Saisir sommeil et énergie (rien depuis 3 jours)','sante']);
if(stats().rech<1)a.push(['Lire un article et remplir 1 fiche recherche cette semaine','recherche']);
const lc=D.comp.map((v,i)=>[v,i]).sort((p,q)=>p[0]-q[0])[0];if(lc[0]<2)a.push(['Progresser en « '+SK[lc[1]][0]+' » (niveau '+lc[0]+'/5)','comp']);
if(Date.now()-(D._exp||0)>6048e5)a.push(['Exporter une sauvegarde','data']);
return a.slice(0,5)}
function multiOver(){try{const c=JSON.parse(localStorage.getItem(PF+'courses')||'null');if(!Array.isArray(c))return null;let n=0;const t=td(),cfg=JSON.parse(localStorage.getItem(PF+'rev:cfg')||'{}');[['j0',0],['j1',1],['j2',2],['j3',3],['j7',7],['j15',15],['j21',21],['j30',30]].forEach(([k,o])=>{const x=cfg[k]||{};if(x.on===0||x.on===false)return;const off=x.off!=null?+x.off:o;c.forEach(cc=>{if(cc.dateAdded&&(cc.checkpoints||{})[k]===false&&add(cc.dateAdded,off)<t)n++})});return n}catch(e){return null}}
function routineToday(){try{const r=JSON.parse(localStorage.getItem(PF+'routine:v1')||'null');if(!r)return null;return Object.values((r.done||{})[td()]||{}).filter(Boolean).length}catch(e){return null}}
function weeksBars(){const w=[];for(let i=7;i>=0;i--){const a=add(td(),-7*i-6),b=add(td(),-7*i);w.push(L('recherche').filter(x=>x.date&&x.date>=a&&x.date<=b).length)}const mx=Math.max(3,...w),bw=300/8;return `<svg viewBox="0 0 300 80" width="100%">${w.map((v,i)=>`<rect x="${i*bw+6}" y="${64-v/mx*52}" width="${bw-12}" height="${v/mx*52}" rx="3" fill="#C9A24B"/><text x="${i*bw+bw/2}" y="${60-v/mx*52}" font-size="9" text-anchor="middle">${v||''}</text><text x="${i*bw+bw/2}" y="76" font-size="8.5" text-anchor="middle">S-${7-i||'0'}</text>`).join('')}</svg>`}
function semBars(){const d=notesData(),w=300/6;return `<svg viewBox="0 0 300 92" width="100%"><line x1="0" x2="300" y1="40" y2="40" stroke="currentColor" stroke-dasharray="3" opacity=".4"/>${d.sems.map((x,i)=>{const h=x.avg===null?0:x.avg*3.6;return `<rect x="${i*w+8}" y="${76-h}" width="${w-16}" height="${h}" rx="3" fill="${x.avg>=14?'#2E8B57':x.avg>=10?'#D08A1A':'#C0392B'}"/><text x="${i*w+w/2}" y="${72-h}" font-size="9" text-anchor="middle">${x.avg===null?'':x.avg.toFixed(1)}</text><text x="${i*w+w/2}" y="88" font-size="9" text-anchor="middle">${x.s}</text>`}).join('')}</svg>`}
function home(){const s=stats(),nd=notesData(),ck=pchk(),done=ck.filter(c=>c.st=='Fait').length,pw=L('passerelle').reduce((t,x)=>t+fw(x),0),axOk=AX.filter(x=>L('passerelle').filter(p=>p.axe==x).reduce((t,p)=>t+fw(p),0)>=6).length,per=period(),acts=actions(),dl=deadlines(),mo=multiOver(),rt=routineToday(),E=ecoCore('life');
const now=new Date(),h=now.getHours(),greet=h<5||h>=18?'Bonsoir':'Bonjour',ds=now.toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long',year:'numeric'});
const K=(v,l,c)=>`<div class="k ${c||''}"><b>${v}</b><span>${l}</span></div>`,cp=D.comp.reduce((t,x)=>t+x,0)/D.comp.length,pubs=L('publications').filter(x=>x.statut=='Publié / présenté'||x.statut=='Accepté').length;
const c10d=c10(),nvc=c10d?CNAMES.filter((_,i)=>(c10d[i+1]||{}).tut>=3&&(c10d[i+1]||{}).date).length:null;const last=L('stages').slice().sort((p,q)=>(q.debut||'').localeCompare(p.debut||''))[0],tr=s.rev?Math.round(s.epargneInvest/s.rev*100)+' %':'—';
return `${bk()}<div class="hero"><h1>${greet} Naw</h1><p style="text-transform:capitalize">${ds}</p><span class="per">${per[0]}</span><p>${per[1]}</p></div>
<div class="dash2"><div class="card wide"><h3>Frise 2026 – 2036</h3>${timeline()}</div>
<div class="card"><h3>🎯 Actions prioritaires</h3>${acts.length?acts.map((x,i)=>`<div class="act" onclick="go('${x[1]}')"><i>${i+1}</i><span>${esc(x[0])}</span></div>`).join(''):'<p class="m">Rien d\'urgent : continue sur ta lancée.</p>'}</div>
<div class="card"><h3>📆 Prochaines échéances</h3>${dl.length?dl.map(x=>`<div class="ddl" onclick="go('${x.tab}')"><span>${esc(x.l)}</span><b class="${x.late?'late':''}">${esc(x.d)}${x.late?' ⚠':''}</b></div>`).join(''):'<p class="m">Aucune échéance datée. Ajoute des dates dans la checklist passerelle ou tes stages.</p>'}</div>
<div class="card wide"><h3>Indicateurs (indépendants, sans score unique)</h3><div class="grid">${K(nd.all===null?'—':nd.all.toFixed(2),'moyenne IFSI /20',nd.all===null?'':nd.all>=14?'good':nd.all>=10?'mid':'warn')}${K(done+'/'+ck.length,'pièces du dossier',done==ck.length?'good':'')}${K(axOk+'/5','axes documentés (poids ≥ 6)',axOk>=4?'good':axOk>=2?'mid':'warn')}${K(pw,'poids qualité des preuves')}${K(L('stages').length,'stages')}${nvc===null?'':K(nvc+'/10','compétences cliniques validées',nvc>=7?'good':nvc>=3?'mid':'')}${K(s.rech,'fiches recherche · 7 j',s.rech?'good':'mid')}${K(pubs,'publications acceptées')}${K(cp.toFixed(1)+'/5','compétences (moy.)')}${K(s.sleep===null?'—':s.sleep.toFixed(1)+' h','sommeil moy. 7 j',s.sleep===null?'':s.sleep>=7?'good':s.sleep>=6?'mid':'warn')}${K(s.sport,'séances de sport · 7 j')}</div><p class="m">Ces indicateurs mesurent ta préparation, pas une probabilité d'admission.</p></div>
<div class="card"><h3>📊 Académique</h3>${semBars()}<p class="m">Moyenne par semestre. ${nd.a.filter(x=>+x.note<10).length?nd.a.filter(x=>+x.note<10).length+' note(s) sous 10/20.':'Aucune note sous 10/20.'} <a href="#" onclick="go('notes');return false">Détail →</a></p></div>
<div class="card"><h3>🔬 Recherche</h3>${weeksBars()}<p class="m">Fiches par semaine (8 dernières). ${L('recherche').length} fiche(s), ${L('publications').length} publication(s)/poster(s).</p></div>
<div class="card"><h3>🏥 Stages</h3><p class="m">${L('stages').length} stage(s) enregistré(s).${last?' Dernier : <b>'+esc(last.lieu)+'</b> ('+esc(last.debut)+').':' Aucun pour l\'instant.'}${last&&!last.bilan?' Bilan à rédiger.':''}</p></div>
<div class="card"><h3>💰 Finance</h3><div class="grid">${K(s.liq+' €','liquidités',s.liq<0?'warn':'')}${K(s.pat+' €','patrimoine')}${K(tr,'taux d\'épargne')}</div></div>
<div class="card"><h3>🧠 Compétences</h3>${SK.slice().map((x,i)=>[x[0],D.comp[i]]).sort((p,q)=>p[1]-q[1]).slice(0,3).map(x=>`<div class="row"><span class="m">${esc(x[0])}</span><span class="m">${x[1]}/5</span></div>${gauge(x[1]/5)}`).join('')}<p class="m">Les 3 plus faibles.</p></div>
<div class="card"><h3>😴 Sommeil · 14 jours</h3>${chart().replace(/^<div class="card"><h3>[^<]*<\/h3>/,'').replace(/<\/div>$/,'')}</div>
<div class="card wide"><h3>🧭 Mon écosystème</h3>${E.html()}<p class="m">Routine du jour : ${rt===null?'non connecté':rt+' bloc(s) cochés'} · Révisions en retard (Multi-DA) : ${mo===null?'non connecté':mo}. Lecture seule : les données se partagent dans ce navigateur, pas entre appareils.</p></div></div>`}

let editK=null,editI=null,searchQ={};
function form(k){const m=M[k];const ed=editK==k&&editI!=null;const cur=ed?L(k)[editI]:null;
return `<div class="card" id="form_${k}"><h3>${ed?'✎ Modifier':'+ Ajouter'} — ${m.n}</h3>${m.f.map(([f,l,t,o,df])=>{const v=cur?(cur[f]||''):(df||'');return `<label>${l}</label>`+(t=='a'?`<textarea id="f_${f}">${esc(v)}</textarea>`:t=='s'?`<select id="f_${f}">${o.map(x=>`<option ${x==v?'selected':''}>${esc(x)}</option>`).join('')}</select>`:`<input id="f_${f}" type="${t=='d'?'date':t=='n'?'number':'text'}" value="${esc(v||(t=='d'&&!ed?td():''))}">`)}).join('')}<div class="row"><button class="btn" onclick="addI('${k}')">${ed?'💾 Enregistrer les modifications':'+ Ajouter'}</button>${ed?`<button class="btn s" onclick="cancelEdit()">Annuler</button>`:''}</div></div>`}
function addI(k){const it={};M[k].f.forEach(([f])=>it[f]=$('#f_'+f).value);if(!Object.values(it).some(v=>v&&v!=td()))return;
const keys=Object.keys(it),isEdit=editK==k&&editI!=null;
if(!isEdit&&L(k).some(o=>keys.every(f=>String(o[f]??'')===String(it[f]??'')))&&!confirm('Une ligne identique existe déjà. L\'ajouter quand même ?'))return;
if(k=='finance'&&(it.type=='Transfert épargne → courant'||it.type=='Transfert investissement → courant')){const ac=accounts(),src=it.type=='Transfert épargne → courant'?'Livret / épargne':'Investissement';if((+it.mt||0)>ac[src]&&!confirm('Ce retrait dépasse le solde actuel du compte ('+Math.round(ac[src]*100)/100+' €). Continuer ?'))return}
if(k=='finance'&&!(+it.mt>0)){alert('Indique un montant supérieur à 0.');return}
if(editK==k&&editI!=null){L(k)[editI]=it;editK=null;editI=null}else{L(k).unshift(it)}
save();render()}
function cancelEdit(){editK=null;editI=null;render()}
function editItem(k,i){editK=k;editI=i;render();setTimeout(()=>{const el=$('#form_'+k);if(el)el.scrollIntoView({behavior:'smooth',block:'start'})},0)}
function del(k,i){if(confirm('Supprimer ?')){L(k).splice(i,1);if(editK==k&&editI==i){editK=null;editI=null}save();render()}}
function searchbox(k){return `<input id="search_${k}" placeholder="🔎 Rechercher dans cette liste…" oninput="doSearch('${k}')" value="${esc(searchQ[k]||'')}">`}
function doSearch(k){searchQ[k]=$('#search_'+k).value;const el=$('#list_'+k);if(el)el.innerHTML=list(k)}
function list(k){const m=M[k];const q=(searchQ[k]||'').toLowerCase().trim();
let arr=L(k).map((x,i)=>({x,i}));
if(q)arr=arr.filter(o=>JSON.stringify(o.x).toLowerCase().includes(q));
if(k=='recherche'&&rf)arr=arr.filter(o=>(o.x.lec||'Lue')==rf);
if(k=='passerelle'){if(pf.sem)arr=arr.filter(o=>o.x.sem==pf.sem);if(pf.axe!=='')arr=arr.filter(o=>o.x.axe==AX[+pf.axe])}
const df=m.f.find(([f,l,t])=>t=='d');
if(df)arr=arr.slice().sort((a,b)=>(b.x[df[0]]||'').localeCompare(a.x[df[0]]||''));
if(!arr.length)return `<p class="m">${L(k).length?'Aucun résultat pour cette recherche.':'Rien pour l\'instant — ajoute ta première entrée ci-dessus.'}</p>`;
return arr.map(({x,i})=>`<div class="card"><div class="row"><b>${esc(x[m.f[0][0]])}</b><span><button class="btn s" onclick="editItem('${k}',${i})">✎</button> <button class="btn s" onclick="del('${k}',${i})">✕</button></span></div>${m.f.slice(1).filter(([f])=>x[f]).map(([f,l])=>`<div class="m"><b>${l.split(' (')[0].split(' :')[0]} :</b> ${esc(x[f])}</div>`).join('')}</div>`).join('')}
function extra(k){const a=L(k);
if(k=='hebdo')return `<div class="card"><h3>🤖 Bilan automatique</h3><p class="m">Remplit le formulaire ci-dessous avec les données de la semaine (Multi-DA, Routine et LIFE-PROJECT). Relis, corrige, puis ajoute.</p><button class="btn" onclick="hebdoAuto()">Pré-remplir depuis mes données</button></div>`;
if(k=='jalons')return `<p class="m">Jalons de long terme avec critère de réussite. <a href="#" onclick="seedJalons();return false">Ajouter des jalons suggérés</a></p>`;
if(k=='finance')return finX();
if(false){const s=stats();const c=s.solde>=0?'var(--g)':'var(--r)';return `<div class="card" style="text-align:center"><span class="m">Solde total (recalculé en temps réel)</span><div style="font-size:32px;font-weight:700;color:${c}">${s.solde} €</div></div><div class="grid"><div class="k"><b>${s.rev} €</b><span>revenus</span></div><div class="k"><b>${s.dep} €</b><span>dépenses</span></div><div class="k"><b>${s.epargneInvest} €</b><span>épargné + investi</span></div><div class="k"><b>${s.formCost} €</b><span>formations/compétences</span></div></div><p class="m">Solde = revenus + épargne + investissements − dépenses − formations. Chaque ajout, modification ou suppression met ce chiffre à jour immédiatement. Ordre : sécurité → capital → compétences → zéro dette de consommation.</p>`}
if(k=='passerelle')return passX();
if(k=='notes')return notesX();
if(k=='sante')return chart()+santeX()+`<p class="m">Sommeil + sport + récupération = variables de performance, pas des récompenses.</p>`;
if(k=='stages')return `<div class="card"><p class="m">🔄 Synchronisé avec Multi-DA${TEST?' TEST':''} : lieu, dates, objectifs et bilan se modifient des deux côtés ; le journal et les questions viennent de Multi-DA (modifie-les là-bas).</p></div>`+clinX()+`<p class="m">Avant : anatomie, physio, pathologies, pharmaco, gestes. Pendant : patient → problème → hypothèses → prise en charge → résultat → question scientifique.</p>`;
if(k=='recherche')return rechX()+`<p class="m">1 article/semaine suffit en L1. Grille : Question → Méthode → Résultat → Implications → Retenu → Évolution.</p>`;
if(k=='publications')return `<p class="m">Chaque fiche de recherche solide peut devenir un poster ou une communication. Vise au moins une trace écrite par stage/projet marquant (poster de stage, résumé de mémoire, communication en journée scientifique).</p>`;
return ''}
const CNAMES=["Évaluer une situation clinique et établir un diagnostic", "Concevoir et conduire un projet de soins", "Accompagner une personne dans ses soins quotidiens", "Mettre en œuvre des actions diagnostiques et thérapeutiques", "Initier et mettre en œuvre des soins éducatifs et préventifs", "Communiquer et conduire une relation de soins", "Analyser la qualité des soins et améliorer sa pratique", "Rechercher et traiter des données professionnelles et scientifiques", "Organiser et coordonner des interventions soignantes", "Informer, former des professionnels et des personnes en formation"];
function c10(){try{return JSON.parse(localStorage.getItem(PF+'comp10')||'null')}catch(e){return null}}
function pushComp(n){const c=(c10()||{})[n];if(!c)return;const t='Compétence '+n+' validée : '+CNAMES[n-1];if(L('passerelle').some(x=>x.titre==t)){alert('Déjà dans le dossier.');return}D.passerelle=D.passerelle||[];D.passerelle.unshift({id:'c'+Date.now(),titre:t,sem:'S1',type:'Compétence',axe:AX[1],force:c.tut>=4?'Très solide':'Solide',piece:'Multi-DA > Compétences (preuves de stage)',obtenu:c.date||'',det:(c.proofs||[]).map(p=>p.stage+' : '+p.desc).join(' ; '),date:td()});save();render()}
function clinX(){const c=c10();if(!c)return '<div class="card"><h3>Compétences cliniques</h3><p class="m">Multi-DA n\'a pas encore de données sur ce navigateur. Ouvre Multi-DA > Compétences pour les renseigner : la synthèse apparaîtra ici.</p></div>';
const v=n=>{const x=c[n]||{};return (+x.tut>=3&&x.date)};const nv=CNAMES.filter((_,i)=>v(i+1)).length;
return `<div class="card"><h3>🩺 Compétences cliniques (depuis Multi-DA) · ${nv}/10 validées</h3>${gauge(nv/10)}${CNAMES.map((t,i)=>{const x=c[i+1]||{auto:0,tut:0,proofs:[]};return `<div class="row" style="border-top:1px solid var(--b);padding:6px 0"><span>${i+1}. ${esc(t)}<br><span class="m">Auto ${x.auto||0}/4 · Tuteur ${x.tut||0}/4${x.date?' · validée le '+esc(x.date):''} · ${(x.proofs||[]).length} preuve(s)</span></span>${v(i+1)?`<button class="btn s" onclick="pushComp(${i+1})">→ dossier</button>`:''}</div>`}).join('')}<p class="m">« → dossier » ajoute la compétence validée comme preuve de l'axe ② (sans doublon).</p></div>`}
/* ---- Passerelle : checklist, axes, récit ---- */
const FW={'Faible':1,'Solide':2,'Très solide':3},fw=x=>FW[x.force]||2;
const PCHK=['Vérifier les conditions et le calendrier officiels de la passerelle (université)','Relevés de notes IFSI à jour','Attestations et évaluations de stage','CV à jour','Lettre de motivation / projet médical','Lettres de recommandation (cadre de santé, tuteur, enseignant)','Récit du PASS : parcours expliqué, pas caché','Preuves de recherche : fiches, poster, publications','Préparation de l\'oral (questions types, entraînement)','Pièces administratives et copies','Dépôt du dossier dans les délais'];
let pf={sem:'',axe:''},rf='';
function rfS(v){rf=rf===v?'':v;render()}
function rechX(){const a=L('recherche'),st=['À lire','En cours','Lue','À relire'],n=s=>a.filter(x=>(x.lec||'Lue')==s).length;return `<div class="card"><h3>📚 Bibliothèque</h3>${st.map(s=>`<button class="btn s" style="${rf===s?'outline:2px solid var(--a)':''}" onclick="rfS('${s}')">${s} · ${n(s)}</button> `).join('')}<p class="m">Clique un statut pour filtrer la liste. ${a.filter(x=>x.doi).length} article(s) avec DOI/lien · ${a.filter(x=>x.crit).length} avec appréciation critique.</p></div>`}
function pchk(){if(!Array.isArray(D.pchk)||!D.pchk.length)D.pchk=PCHK.map(t=>({t,st:'À faire',due:''}));return D.pchk}
function passScore(){const a=L('passerelle'),w=a.reduce((s,x)=>s+fw(x),0),ck=pchk(),c=ck.filter(x=>x.st=='Fait').length/ck.length;return 0.6*Math.min(1,w/(targets().passerelle*2))+0.4*c}
function pcSet(i,f,v){pchk()[i][f]=v;save();render()}
function pcAdd(){const v=$('#pc_new').value.trim();if(!v)return;pchk().push({t:v,st:'À faire',due:''});save();render()}
function pcDel(i){if(confirm('Retirer cette ligne de la checklist ?')){pchk().splice(i,1);save();render()}}
function prSet(i,v){D.pr=D.pr||{};D.pr[i]=v;save()}
function pfS(k,v){pf[k]=pf[k]===v?'':v;render()}
function passX(){return passX0()+passY()}
function passX0(){const a=L('passerelle'),ck=pchk(),done=ck.filter(c=>c.st=='Fait').length,t0=td(),late=ck.filter(c=>c.st!='Fait'&&c.due&&c.due<t0),nxt=ck.filter(c=>c.st!='Fait'&&c.due&&c.due>=t0).sort((x,y)=>x.due<y.due?-1:1)[0];
const ax=AX.map(t=>{const e=a.filter(x=>x.axe==t),w=e.reduce((s,x)=>s+fw(x),0);return{t,n:e.length,w,p:Math.min(1,w/6)}}),un=a.filter(x=>!x.axe).length,sc=passScore();
const chip=(on,fn,l)=>`<button class="btn s" style="${on?'outline:2px solid var(--o)':''}" onclick="${fn}">${l}</button> `;
return `<div class="card"><h3>🎯 État du dossier</h3>${gauge(sc,true)}<p class="m">Pièces faites : ${done}/${ck.length} · Preuves : ${a.length} (poids qualité ${a.reduce((s,x)=>s+fw(x),0)}) · ${late.length?`<b style="color:var(--r)">${late.length} en retard</b>`:'aucun retard'}${nxt?` · prochaine échéance : <b>${esc(nxt.due)}</b> — ${esc(nxt.t)}`:''}</p><p class="m">Le score compte 60 % la <b>qualité</b> des preuves (faible 1, solide 2, très solide 3) et 40 % la checklist : une preuve solide pèse plus qu'une simple entrée de plus. <b>Ce score mesure ta préparation, pas une probabilité d'admission.</b></p></div>
<div class="card"><h3>✅ Checklist du dossier & calendrier</h3><p class="m">Liste générale à adapter : vérifie les règles et dates officielles de l'université au moment de candidater.</p>${ck.map((c,i)=>`<div style="border-top:1px solid var(--b,#ddd);padding:8px 0"><div class="row"><span ${c.st=='Fait'?'style="text-decoration:line-through;opacity:.6"':''}>${esc(c.t)}</span><button class="btn s" onclick="pcDel(${i})">✕</button></div><div class="row"><select onchange="pcSet(${i},'st',this.value)">${['À faire','En cours','Fait'].map(o=>`<option ${o==c.st?'selected':''}>${o}</option>`).join('')}</select><input type="date" value="${esc(c.due||'')}" onchange="pcSet(${i},'due',this.value)">${c.st!='Fait'&&c.due&&c.due<t0?'<span style="color:var(--r)">⚠ en retard</span>':''}</div></div>`).join('')}<div class="row" style="margin-top:8px"><input id="pc_new" placeholder="Ajouter une pièce ou une étape…"><button class="btn" onclick="pcAdd()">+</button></div></div>
<div class="card"><h3>🧭 Les 5 axes du dossier</h3><p class="m">Rattache chaque preuve à un axe (champ « Axe du dossier servi »). Objectif : poids ≥ 6 par axe (ex. 3 preuves solides).${un?` ${un} preuve(s) sans axe.`:''}</p>${ax.map((x,i)=>`<div style="margin-top:10px"><div class="row"><b>${x.t}</b><span class="m">${x.n} preuve(s) · poids ${x.w}/6</span></div>${gauge(x.p)}<label>Mon récit pour cet axe (lettre, oral)</label><textarea onchange="prSet(${i},this.value)">${esc((D.pr||{})[i]||'')}</textarea></div>`).join('')}<p class="m">Récit : PASS difficile → réorientation réfléchie → excellence en sciences infirmières → clinique → recherche → projet médical. Le PASS est expliqué, pas caché.</p></div>
<div class="card"><h3>🔎 Filtrer les preuves</h3><div>${S1.map(s=>chip(pf.sem==s,`pfS('sem','${s}')`,`${s} · ${a.filter(x=>x.sem==s).length}`)).join('')}</div><div style="margin-top:6px">${AX.map((t,i)=>chip(pf.axe===String(i),`pfS('axe','${i}')`,t.split(' ')[0]+' '+a.filter(x=>x.axe==t).length)).join('')}</div></div>`}
function gl(key,seed){if(!Array.isArray(D[key]))D[key]=(seed||[]).map(x=>Object.assign({},x));return D[key]}
function glSet(k,i,f,v){gl(k)[i][f]=v;save()}
function glDel(k,i){if(confirm('Supprimer cette ligne ?')){gl(k).splice(i,1);save();render()}}
function glAdd(k){gl(k).push({});save();render()}
function glCard(title,key,cols,seed,note){const a=gl(key,seed);return `<div class="card"><h3>${title}</h3>${note?`<p class="m">${note}</p>`:''}${a.map((x,i)=>`<div style="border-top:1px solid var(--b);padding:6px 0"><div class="row"><div style="flex:1">${cols.map(([f,l,t,o])=>`<label>${l}</label>${t=='s'?`<select onchange="glSet('${key}',${i},'${f}',this.value)">${o.map(z=>`<option ${x[f]==z?'selected':''}>${z}</option>`).join('')}</select>`:t=='a'?`<textarea onchange="glSet('${key}',${i},'${f}',this.value)">${esc(x[f]||'')}</textarea>`:`<input type="${t=='d'?'date':'text'}" value="${esc(x[f]||'')}" onchange="glSet('${key}',${i},'${f}',this.value)">`}`).join('')}</div><button class="btn s" onclick="glDel('${key}',${i})">✕</button></div></div>`).join('')}<button class="btn" onclick="glAdd('${key}')">+ Ajouter</button></div>`}
function txtSet(k,v){D[k]=v;save();const e=$('#wc_'+k);if(e)e.textContent=(v.trim()?v.trim().split(/\s+/).length:0)+' mots'}
function txtCard(title,key,ph){const v=D[key]||'';return `<div class="card"><h3>${title}</h3><textarea style="min-height:160px" placeholder="${ph}" oninput="txtSet('${key}',this.value)">${esc(v)}</textarea><p class="m" id="wc_${key}">${v.trim()?v.trim().split(/\s+/).length:0} mots</p></div>`}
const ST3=['À faire','En cours','Fait'];
function synth(){const a=L('passerelle'),nd=notesData(),c=c10(),nv=c?CNAMES.filter((_,i)=>(c[i+1]||{}).tut>=3&&(c[i+1]||{}).date).length:null,ax=AX.map(x=>({x,w:a.filter(p=>p.axe==x).reduce((t,p)=>t+fw(p),0),n:a.filter(p=>p.axe==x).length})),weak=ax.filter(z=>z.w<6),sm=S1.filter(s=>!a.some(p=>p.sem==s)).slice(0,3);
return [`${a.length} preuve(s) au total (${a.filter(p=>p.force=='Très solide').length} très solide(s), ${a.filter(p=>p.force=='Faible').length} faible(s)).`,nd.all!=null?`Moyenne IFSI : ${nd.all.toFixed(2)}/20${nd.rk.length?' · dernier classement : top '+nTop(nd.rk[nd.rk.length-1])+' %':''}.`:'Aucune note saisie.',`${L('stages').length} stage(s)${nv!=null?', '+nv+'/10 compétences cliniques validées':''}.`,`${L('recherche').length} fiche(s) de recherche, ${L('publications').length} publication(s)/poster(s).`,weak.length?'Axes insuffisamment documentés : '+weak.map(z=>z.x.slice(2)+' ('+z.w+'/6)').join(' ; ')+'.':'Tous les axes ont un poids ≥ 6.',sm.length?'Aucune preuve rattachée aux semestres : '+sm.join(', ')+'.':''].filter(Boolean)}
function passY(){return `<div class="card"><h3>🧾 Synthèse automatique des preuves</h3>${synth().map(x=>`<p class="m" style="margin:3px 0">• ${esc(x)}</p>`).join('')}<p class="m">Mesure ta préparation, pas une probabilité d'admission.</p></div>`
+glCard('✔ Conditions d\'éligibilité à vérifier','pelig',[['t','Condition','t'],['st','Statut','s',['À vérifier','Vérifiée : OK','Bloquante']],['src','Source (lien, règlement)','t']],[{t:'Diplôme et année d\'études requis'},{t:'Nombre de tentatives autorisées'},{t:'Pièces exigées par l\'université'},{t:'Épreuves : dossier, oral, autre'},{t:'Capacité d\'accueil et mode de sélection'}].map(x=>Object.assign({st:'À vérifier'},x)),'Liste à confirmer sur le site officiel de l\'université avant toute candidature.')
+glCard('📅 Calendrier officiel de candidature','pcal',[['t','Étape','t'],['d','Date','d'],['url','Lien officiel','t'],['st','Statut','s',ST3]],[],'Recopie les dates officielles ; elles remontent dans « Prochaines échéances ».')
+glCard('🎤 Checklist de préparation à l\'oral','poral',[['t','Point','t'],['st','Statut','s',ST3]],['Pourquoi médecine, pourquoi maintenant, pourquoi médecin','Raconter le PASS sans le cacher','Citer 3 situations de stage marquantes','Présenter un projet de recherche','Réponses à 10 questions types, chronométrées','Entraînement à voix haute devant quelqu\'un'].map(t=>({t,st:'À faire'})))
+glCard('❓ Questions d\'oral et réponses travaillées','pqa',[['q','Question','t'],['a','Ma réponse travaillée','a']],[])
+glCard('✉ Lettres de recommandation','prec',[['nom','Personne','t'],['fonction','Fonction','t'],['st','Statut','s',['À demander','Demandée','Reçue']],['d','Date','d']],[])
+txtCard('📝 Lettre de motivation','plm','Premier jet de la lettre…')+txtCard('🩺 Projet médical (rédaction)','ppm','Pourquoi médecine, pourquoi toi, quelle trajectoire…')}
function planX(){const Y=[['2026-27','IFSI 1','Rentrée en septembre 2026 : méthodes de révision, premiers stages, sport et sommeil réguliers, premières fiches de recherche.'],['2027-28','IFSI 2','Stages plus complexes, premier projet de recherche, premiers résultats écrits (poster, résumé).'],['2028-29','IFSI 3','Mémoire, dossier passerelle complet, oral préparé, DEI.'],['2029-30','Après le DEI','Selon les décisions : candidature passerelle, premier poste IDE, ou master.'],['2030-31','Option ouverte','Trajectoire A : études de médecine · B : IDE spécialisé · C : master recherche.'],['2031-32','Option ouverte','Consolider le parcours choisi, publier au moins une fois.'],['2032-33','Option ouverte','Montée en responsabilité ou spécialisation.'],['2033-34','Option ouverte','Recherche personnelle plus autonome.'],['2034-35','Option ouverte','Préparer la suite (spécialité, doctorat ou poste).'],['2035-36','Horizon 2036','Bilan des dix ans et nouvelle trajectoire.']];
const T=[['A · Passerelle → médecine → recherche','Passerelle acceptée → études de médecine → spécialité → recherche clinique.','Critères : dossier passerelle complet, moyenne et rang solides, 3+ preuves par axe.'],['B · IDE spécialisé (IADE / IPA)','DEI → expérience IDE → master → IADE ou IPA.','Critères : stage en service ciblé, projet de master, formation continue validée.'],['C · IDE chercheuse','DEI → master recherche → doctorat en sciences infirmières.','Critères : 1 publication, projet de recherche encadré, anglais scientifique.']];
const J=L('jalons');return `<div class="card"><h3>📆 Année par année (indicatif)</h3><p class="m">Ces repères sont une base de travail : ajuste-les selon ton parcours réel. Les décisions de 2029 dépendent du dossier passerelle et des résultats.</p>${Y.map(x=>`<div style="border-top:1px solid var(--b);padding:6px 0"><b>${x[0]} · ${x[1]}</b><p class="m" style="margin:2px 0">${x[2]}</p></div>`).join('')}</div><div class="card"><h3>🛤 Trajectoires possibles</h3>${T.map(x=>`<div style="border-top:1px solid var(--b);padding:6px 0"><b>${x[0]}</b><p class="m" style="margin:2px 0">${x[1]}</p><p class="m" style="margin:2px 0">${x[2]}</p></div>`).join('')}</div><div class="card"><h3>🏁 Jalons suivis : ${J.filter(j=>j.st=='Atteint').length}/${J.length}</h3>${J.length?gauge(J.filter(j=>j.st=='Atteint').length/J.length):'<p class="m">Aucun jalon : ouvre « Jalons » ou ajoute les jalons suggérés.</p>'}<button class="btn" onclick="seedJalons()">Ajouter des jalons suggérés</button> <button class="btn s" onclick="go('jalons')">Gérer les jalons</button></div>`}
function seedJalons(){if(L('jalons').length&&!confirm('Ajouter des jalons suggérés en plus des tiens ?'))return;D.jalons=D.jalons||[];[['Valider S1 et S2 avec une moyenne supérieure à 12','2027','Commune','Moyenne ≥ 12, aucune UE sous 10'],['Premier poster ou résumé écrit','2028','C · IDE → recherche','1 trace écrite relue par un encadrant'],['Dossier passerelle complet (checklist 100 %)','2029','A · Passerelle → médecine','Toutes les pièces faites, 5 axes à poids ≥ 6'],['DEI obtenu','2029','Commune','Diplôme validé'],['Choix de trajectoire documenté','2029','Commune','Décision écrite avec critères'],['Première publication ou communication','2031','C · IDE → recherche','1 publication acceptée'],['Master ou spécialité entamé','2031','B · IDE → IADE / IPA','Inscription validée']].forEach(x=>D.jalons.push({id:'j'+Math.random().toString(36).slice(2,8),jalon:x[0],annee:x[1],traj:x[2],crit:x[3],st:'À faire'}));save();render()}
function dataX(){const E=ecoCore('life');return `<div class="card"><h3>Données et paramètres</h3><p class="m">Version ${VER} · schéma 2 · environnement ${TEST?'TEST':'production'}. Cet export ne contient que les données de LIFE-PROJECT.</p><h3 style="margin-top:12px">Thème</h3><div>${THEMES.map(t=>`<button class="btn s" style="${(localStorage.getItem('life-theme')||'auto')==t[0]?'outline:2px solid var(--a)':''}" onclick="themeSet('${t[0]}')">${t[1]}</button> `).join('')}</div><h3 style="margin-top:12px">Historique des exports</h3>${(D._bk||[]).slice().reverse().map(x=>`<p class="m" style="margin:2px 0">${new Date(x.d).toLocaleString('fr-FR')} · ${x.n} entrée(s)</p>`).join('')||'<p class="m">Aucun export enregistré.</p>'}<h3 style="margin-top:12px">Les trois applications</h3>${E.html()}<p class="m">Chaque appli exporte et restaure uniquement ses propres données.</p></div>`}
function printCV(){document.body.classList.add('print-cv');const f=()=>{document.body.classList.remove('print-cv');window.removeEventListener('afterprint',f)};window.addEventListener('afterprint',f);window.print()}
function cvX(){const st=L('stages').slice().sort((x,y)=>(y.debut||'').localeCompare(x.debut||'')),c=c10(),val=c?CNAMES.filter((_,i)=>(c[i+1]||{}).tut>=3&&(c[i+1]||{}).date):[],fm=L('formations').filter(x=>x.st=='Terminée'||x.st=='Validée'),pu=L('publications').filter(x=>x.statut=='Publié / présenté'||x.statut=='Accepté'),sk=SK.map((s,i)=>[s[0],D.comp[i]]).filter(x=>x[1]>=3),rs=L('recherche').filter(x=>x.lec!='À lire').length,nd=notesData();
const sec=(t,b)=>b?`<h4 style="margin:12px 0 4px;border-bottom:1px solid var(--b)">${t}</h4>${b}`:'';
return `<div class="card no-print"><h3>🖨 CV exportable</h3><p class="m">Génère un CV propre à partir de tes données (stages, compétences validées, formations, recherche). Dans la fenêtre d'impression, choisis « Enregistrer en PDF ».</p><button class="btn" onclick="printCV()">Imprimer / PDF du CV</button></div>
<div id="cvarea" class="card"><h2 style="margin-top:0">Naw</h2><p class="m">Étudiante en soins infirmiers (IFSI Bichat) · Université Paris Cité</p>${sec('Formation','<p class="m" style="margin:2px 0">IFSI Bichat — diplôme d’État d’infirmier (depuis 2026)</p><p class="m" style="margin:2px 0">Université Paris Cité — enseignements universitaires</p>'+(nd.all!=null?'<p class="m" style="margin:2px 0">Moyenne IFSI à ce jour : '+nd.all.toFixed(2)+'/20'+(nd.rk.length?' · classement : top '+nTop(nd.rk[nd.rk.length-1])+' %':'')+'</p>':''))}${sec('Stages',st.map(s=>`<p class="m" style="margin:2px 0"><b>${esc(s.lieu)}</b> · ${esc(s.debut||'')}${s.fin?' → '+esc(s.fin):''}${s.comps?' · compétences '+esc(s.comps):''}</p>`).join(''))}${sec('Compétences cliniques validées ('+val.length+'/10)',val.map(v=>`<p class="m" style="margin:2px 0">${esc(v)}</p>`).join(''))}${sec('Recherche et publications',(rs?`<p class="m" style="margin:2px 0">${rs} article(s) lu(s) et analysé(s)</p>`:'')+pu.map(x=>`<p class="m" style="margin:2px 0">${esc(x.titre)} (${esc(x.type)}${x.revue?', '+esc(x.revue):''}${x.date?', '+esc(x.date.slice(0,4)):''})</p>`).join(''))}${sec('Formations complémentaires',fm.map(x=>`<p class="m" style="margin:2px 0">${esc(x.titre)} — ${esc(x.pf||'')}${x.cert?' · certificat : '+esc(x.cert):''}</p>`).join(''))}${sec('Compétences',sk.map(x=>`<span class="badge">${esc(x[0])} · ${x[1]}/5</span>`).join(''))}${sec('Projets',L('projets').filter(x=>x.st!='Idée').map(x=>`<p class="m" style="margin:2px 0">${esc(x.titre)} (${esc(x.st)})</p>`).join(''))}</div>`}
function hebdoAuto(){const t=td(),d7=add(t,-6),sv=(k,v)=>{const e=$('#f_'+k);if(e)e.value=v};
let q=[];try{q=JSON.parse(localStorage.getItem(PF+'qcm')||'[]')}catch(e){}const qw=q.filter(x=>x.date>=d7&&x.total>0),qt=qw.reduce((s,x)=>s+x.total,0),qc=qw.reduce((s,x)=>s+x.correct,0),mo=multiOver(),nd=notesData();
sv('date',t);
sv('etu','Moyenne IFSI : '+(nd.all==null?'—':nd.all.toFixed(2)+'/20')+'. Révisions en retard (Multi-DA) : '+(mo==null?'non connecté':mo)+'. QCM cette semaine : '+(qt?Math.round(qc/qt*100)+' % sur '+qt+' questions':'aucun')+'.'+(notesData().ue.some(x=>x.avg<10)?' UE à consolider : '+nd.ue.filter(x=>x.avg<10).map(x=>x.ue).join(', ')+'.':''));
const cur=L('stages').filter(s=>s.debut&&s.debut<=t&&(!s.fin||s.fin>=t)),c=c10(),nv=c?CNAMES.filter((_,i)=>(c[i+1]||{}).tut>=3&&(c[i+1]||{}).date).length:null;
sv('stg',(cur.length?'Stage en cours : '+cur.map(s=>s.lieu).join(', ')+'. ':'Pas de stage en cours. ')+(nv==null?'':nv+'/10 compétences cliniques validées.'));
const rc=L('recherche').filter(x=>x.date&&x.date>=d7);sv('rec',rc.length?rc.length+' fiche(s) : '+rc.map(x=>x.sujet).join(' ; '):'Aucune fiche cette semaine.');
const mk=t.slice(0,7),ms=finMonths()[mk]||{rev:0,dep:0},s=stats();sv('fin','Ce mois : revenus '+ms.rev+' €, dépenses '+ms.dep+' €. Liquidités '+s.liq+' €, épargne '+s.ep+' €, investi '+s.inv+' €.');
let rd=0;try{const r=JSON.parse(localStorage.getItem(PF+'routine:v1')||'null');if(r&&r.done)for(let i=0;i<7;i++)rd+=Object.values(r.done[add(t,-i)]||{}).filter(Boolean).length}catch(e){}
sv('san','Sommeil moyen 7 j : '+(s.sleep==null?'—':s.sleep.toFixed(1)+' h')+' ; sport : '+s.sport+' séance(s) ; blocs Routine cochés : '+rd+'.');
const ac=actions();sv('car',ac[0]?ac[0][0]:'Entretenir le dossier (une preuve de plus).');sv('next',ac.slice(0,3).map((x,i)=>(i+1)+'. '+x[0]).join('\n'))}
/* ---- Notes & classement ---- */
const NSEMS=S1;
function nSrc(){const own=L('notes').map(x=>Object.assign({src:'LIFE'},x)),sig=x=>[x.ue,x.intitule||'',x.type,x.date].join('|'),have=new Set(own.map(sig));let mu=[];try{mu=JSON.parse(localStorage.getItem(PF+'notes')||'[]').map(x=>Object.assign({src:'Multi-DA'},x)).filter(x=>!have.has(sig(x)))}catch(e){}return own.concat(mu)}
function nCfg(){try{return JSON.parse(localStorage.getItem(PF+'notes:cfg')||'{"s":"ects"}')}catch(e){return{s:'ects'}}}
const nW=e=>+e.coef>0?+e.coef:1;
const nAvg=l=>{const c=l.reduce((t,e)=>t+nW(e),0);return c?l.reduce((t,e)=>t+ +e.note*nW(e),0)/c:null};
function nUE(l){const m={};l.forEach(e=>{const k=e.ue||'Sans UE';(m[k]=m[k]||[]).push(e)});return Object.keys(m).map(k=>({ue:k,n:m[k].length,avg:nAvg(m[k]),ects:Math.max(0,...m[k].map(e=>+e.ects||0)),coef:m[k].reduce((t,e)=>t+nW(e),0),sem:m[k][0].sem}))}
function nGrp(l){const u=nUE(l);if(!u.length)return{avg:null,note:''};let mode=nCfg().s||'ects',note='';if(mode=='ects'&&u.some(x=>!(x.ects>0))){mode='equal';note='ECTS manquants : poids égal par UE.'}const w=x=>mode=='ects'?x.ects:mode=='coef'?x.coef:1,sw=u.reduce((t,x)=>t+w(x),0);return{avg:sw?u.reduce((t,x)=>t+x.avg*w(x),0)/sw:null,note}}
const nTop=e=>+e.rang>0&&+e.eff>0?Math.max(1,Math.round(+e.rang/+e.eff*100)):null;
function notesData(){const all=nSrc(),a=all.filter(e=>e.statut!=='À venir'&&e.note!==''&&e.note!=null&&!isNaN(+e.note)),up=all.filter(e=>e.statut==='À venir').sort((x,y)=>(x.date||'9').localeCompare(y.date||'9'));
const sems=NSEMS.map(s=>{const e=a.filter(x=>x.sem==s),g=nGrp(e),rk=e.filter(x=>nTop(x)!=null),pc=rk.length?rk.reduce((t,x)=>t+(+x.rang)/(+x.eff),0)/rk.length:null;return{s,n:e.length,avg:g.avg,note:g.note,pc}});
const years=[1,2,3].map(y=>Object.assign({y},nGrp(a.filter(e=>e.sem==NSEMS[2*y-2]||e.sem==NSEMS[2*y-1]))));
const types=['Théorique','Pratique','Oral','Stage','Autre'].map(t=>({t,n:a.filter(e=>e.type==t).length,avg:nAvg(a.filter(e=>e.type==t))})).filter(x=>x.n);
return{a,up,sems,years,types,ue:nUE(a),all:nGrp(a).avg,rk:a.filter(e=>nTop(e)!=null).sort((x,y)=>(x.date||'').localeCompare(y.date||''))}}
function notesAvg(){const d=notesData();return d.all===null?'—':d.all.toFixed(2)+'/20'}
function notesSum(){const d=notesData();return d.sems.filter(x=>x.n).map(x=>`<div style="margin-bottom:6px"><b>${x.s}</b> <span class="m">${x.avg.toFixed(2)}/20 · ${x.n} note(s)${x.pc!==null?' · rang moyen : top '+Math.max(1,Math.round(x.pc*100))+' %':''}</span></div>`).join('')}
function notesX(){const d=notesData(),low=d.ue.filter(x=>x.avg<12).sort((x,y)=>x.avg-y.avg).slice(0,6),w=300/6,ms=nSrc().filter(x=>x.src=='Multi-DA').length;
const bars=d.sems.map((x,i)=>{const h=x.avg===null?0:x.avg*3.6;return `<rect x="${i*w+8}" y="${76-h}" width="${w-16}" height="${h}" rx="3" fill="${x.avg>=14?'#2e8b57':x.avg>=10?'#d08a1a':'#c0392b'}"/><text x="${i*w+w/2}" y="${72-h}" font-size="9" text-anchor="middle">${x.avg===null?'':x.avg.toFixed(1)}</text><text x="${i*w+w/2}" y="88" font-size="9" text-anchor="middle">${x.s}</text>`}).join('');
const spark=d.rk.length>1?(()=>{const pts=d.rk.map((e,i)=>[10+i*(280/(d.rk.length-1)),70-(100-nTop(e))/100*60]);return `<svg viewBox="0 0 300 80" width="100%"><polyline fill="none" stroke="var(--a)" stroke-width="2" points="${pts.map(p=>p.join(',')).join(' ')}"/>${pts.map(p=>`<circle cx="${p[0]}" cy="${p[1]}" r="3" fill="var(--a)"/>`).join('')}</svg><p class="m">${d.rk.map(e=>'top '+nTop(e)+' %').join(' → ')}</p>`})():'<p class="m">Ajoute au moins deux notes avec rang et effectif pour voir l\'évolution du classement.</p>';
return `<div class="card" style="text-align:center"><span class="m">Moyenne générale (moyennes d'UE pondérées)</span><div style="font-size:32px;font-weight:700">${d.all===null?'—':d.all.toFixed(2)+' / 20'}</div><span class="m">${d.a.length} note(s) · ${ms?ms+' lue(s) depuis Multi-DA (source de saisie)':'saisie ici ou dans Multi-DA > Notes'}</span></div>
<div class="card"><h3>Moyenne par semestre</h3><svg viewBox="0 0 300 94" width="100%"><line x1="0" x2="300" y1="40" y2="40" stroke="currentColor" stroke-dasharray="3" opacity=".4"/>${bars}</svg>${d.sems.filter(x=>x.note).map(x=>`<p class="m">${x.s} : ${x.note}</p>`).join('')}<p class="m">${d.years.filter(y=>y.avg!=null).map(y=>'Année '+y.y+' : '+y.avg.toFixed(2)).join(' · ')||'Moyennes annuelles : à venir.'}</p></div>
<div class="card"><h3>Par UE</h3>${d.ue.sort((x,y)=>x.sem.localeCompare(y.sem)||x.ue.localeCompare(y.ue)).map(x=>`<div class="row"><span>${esc(x.sem)} · ${esc(x.ue)} <span class="m">(${x.n} éval. · ${x.ects?x.ects+' ECTS':'ECTS ?'})</span></span><b style="color:${x.avg<10?'var(--r)':'inherit'}">${x.avg.toFixed(2)}</b></div>`).join('')||'<p class="m">Aucune note.</p>'}</div>
<div class="card"><h3>Par type d'épreuve</h3>${d.types.map(x=>`<span class="badge">${x.t} : ${x.avg.toFixed(2)} (${x.n})</span>`).join('')||'<p class="m">—</p>'}</div>
<div class="card"><h3>UE à consolider</h3>${low.map(x=>`<p class="m" style="margin:2px 0">⚠ ${esc(x.ue)} : ${x.avg.toFixed(2)}/20${x.avg<10?' (sous 10)':''}</p>`).join('')||'<p class="m">Aucune UE fragile détectée.</p>'}</div>
<div class="card"><h3>Évolution du classement</h3>${spark}</div>
<div class="card"><h3>Évaluations à venir</h3>${d.up.map(e=>`<p class="m" style="margin:2px 0">📅 ${esc(e.date||'date ?')} · ${esc(e.ue)} ${esc(e.intitule||'')} (${esc(e.type)})</p>`).join('')||'<p class="m">Rien de planifié.</p>'}</div>
<p class="m">Les notes saisies dans Multi-DA s'ajoutent ici automatiquement (sans doublon). Tu peux aussi saisir ici une ligne qui n'existe pas dans Multi-DA.</p>`}
const LV5=['Aucune pratique','Notions : je comprends le principe','Pratique guidée','Autonome sur cas simples','Autonome sur cas complexes','Capable de former ou de produire un résultat publiable'];
function cm(i){D.cmeta=D.cmeta||[];return D.cmeta[i]=D.cmeta[i]||{preuve:'',date:'',next:'',mode:'Théorique et pratique',hist:[]}}
function cmSet(i,f,v){cm(i)[f]=v;save()}
function cmLvl(i,v){D.comp[i]=v;const c=cm(i);c.hist=(c.hist||[]).concat([{d:td(),v}]).slice(-12);save();render()}
function comp(){return `<div class="card"><h3>Niveaux de maîtrise</h3>${LV5.map((l,i)=>`<p class="m" style="margin:2px 0"><b>${i}</b> · ${l}</p>`).join('')}</div>${SK.map((s,i)=>{const c=cm(i);return `<div class="card"><h3>${s[1]}. ${s[0]} — niveau ${D.comp[i]}/5</h3><p class="m">${LV5[D.comp[i]]}</p><input type="range" min="0" max="5" value="${D.comp[i]}" onchange="cmLvl(${i},+this.value)">${gauge(D.comp[i]/5)}<label>Nature</label><select onchange="cmSet(${i},'mode',this.value)">${['Théorique','Pratique','Théorique et pratique'].map(o=>`<option ${c.mode==o?'selected':''}>${o}</option>`).join('')}</select><label>Preuve (fichier, lien, projet)</label><input value="${esc(c.preuve)}" onchange="cmSet(${i},'preuve',this.value)"><label>Date de validation</label><input type="date" value="${esc(c.date)}" onchange="cmSet(${i},'date',this.value)"><label>Prochaine étape d'apprentissage</label><input value="${esc(c.next)}" onchange="cmSet(${i},'next',this.value)">${(c.hist||[]).length?`<p class="m">Historique : ${c.hist.slice(-6).map(h=>h.d.slice(5)+' → '+h.v).join(' · ')}</p>`:''}</div>`}).join('')}<p class="m">Une certification terminée et maîtrisée > cinq commencées. Hiérarchie : notes/compétences > stages > recherche > projets > formations > extras.</p>`}
function plan(){return plan0()+planX()}
function plan0(){const P=[['2026-27 · IFSI 1','Excellence : major/top niveau, méthodes M1-M5, stages, sport, sommeil, anglais, recherche légère, site opérationnel.'],['2027-28 · IFSI 2','Excellence + différenciation : stages stratégiques, premiers projets de recherche, statistiques, anglais scientifique, réseau hospitalo-universitaire, revenus, capital.'],['2028-29 · IFSI 3','Dossier passerelle : notes, stages cohérents, mémoire, recherche, projet médical clair, CV, lettre, oral, candidature.'],['2029+ · DEI','Passerelle acceptée → médecine. Sinon : emploi IDE + spécialisation/master + 2e candidature si autorisée. Branches parallèles : IADE (2 ans) ou IPA (grade master).'],['Médecine → Recherche','Spécialisation + master santé publique ou recherche → doctorat → CHU / Inserm / université / industrie. Master seul ≠ Inserm : il faut un doctorat.']];
return P.map(p=>`<div class="card"><h3>${p[0]}</h3><div class="m">${p[1]}</div></div>`).join('')+`<div class="card"><h3>Arbre de décision</h3><pre>DEI ─┬─ PASSERELLE → MÉDECINE → spé → master/recherche → doctorat → Inserm/CHU/industrie
     ├─ IADE (2 ans)
     └─ IPA + master</pre><p class="m">Les branches ne sont pas contradictoires : garder plusieurs options ouvertes jusqu'à ce que les données réelles (notes, stages, recherche, passerelle) tranchent.</p></div>
<div class="card"><h3>3 moteurs</h3><div class="m">🧠 Excellence · 🔬 Science · 💰 Capital — une étape principale, plusieurs capitaux en parallèle.</div></div>
<div class="card"><h3>5 méthodes d'élite</h3><div class="m">M1 Fiches de flux (zéro phrase, cause → effet, recto/verso) · M2 Tableau blanc (réécriture de mémoire, corrections en vert) · M3 Grille d'évaluation inversée (UE 4.1) · M4 Carnet de liaison clinique (mécanisme → symptômes → surveillance) · M5 Reverse engineering QCM (3 pièges en rouge) + réécriture espacée J0/J3/J7/J30.</div></div>
<div class="card"><h3>10 règles</h3><div class="m">1 Réussir brillamment l'IFSI · 2 Le site = système de pilotage · 3 Aucune dette de cours · 4 Chaque stage = compétence + question scientifique · 5 Dossier construit sur 3 ans · 6 PASS = preuve de progression · 7 Recherche tôt, faible dose · 8 Anglais, stats, data, IA progressifs · 9 Faibles dépenses = capital · 10 Options ouvertes jusqu'aux données.</div></div>`}
function data(){return data0()+dataX()}
function data0(){return `<div class="card"><h3>Sauvegarde</h3><p class="m" id="pinfo">…</p><p class="m">Les données restent dans ce navigateur. Exporte régulièrement.</p><button class="btn" onclick="ex()">📤 Exporter .json</button><label>Importer (remplace tout)</label><input type="file" accept=".json" onchange="im(this)"><button class="btn" style="background:var(--r)" onclick="if(confirm('Tout effacer ?')){D={};save();location.reload()}">Tout effacer</button></div>`}
function ex(){D._bk=(D._bk||[]).concat([{d:new Date().toISOString(),n:Object.keys(M).reduce((t,k)=>t+(Array.isArray(D[k])?D[k].length:0),0)}]).slice(-10);D._exp=Date.now();save();const b=new Blob([JSON.stringify(Object.assign({_meta:{app:'LIFE-PROJECT',schema:2,ver:VER,env:TEST?'TEST':'PROD',date:td()}},D))],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='programme-major-'+td()+'.json';a.click()}
function backupNow(tag){try{const b=new Blob([JSON.stringify(D)],{type:'application/json'}),x=document.createElement('a');x.href=URL.createObjectURL(b);x.download='programme-major-'+tag+'-'+td()+'.json';x.click()}catch(e){}}
function im(i){const f=i.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{const p=JSON.parse(r.result);if(!p||typeof p!=='object'||Array.isArray(p)||(p._meta&&p._meta.app&&p._meta.app!=='LIFE-PROJECT')){alert("Fichier invalide : ce n'est pas une sauvegarde de ce site.");return}
const ks=Object.keys(M),lines=ks.map(k=>M[k].n+' : '+L(k).length+' → '+(Array.isArray(p[k])?p[k].length:0)).join('\n');
if(p._meta&&p._meta.schema>2&&!confirm('Cette sauvegarde vient d\'une version plus récente du site. Continuer ?'))return;
if(!confirm('Importer cette sauvegarde'+(p._meta?' ('+p._meta.env+' '+p._meta.ver+', '+p._meta.date+')':' (ancien format)')+' ?\nEntrées actuelles → après import :\n'+lines+'\n\nUne sauvegarde de l\'état actuel sera téléchargée avant.')){i.value='';return}
backupNow('avant-import');D=p;if(!D.comp)D.comp=SK.map(s=>0);save();location.reload()}catch(e){alert("Fichier invalide : ce n'est pas un .json exporté depuis ce site (bouton Exporter).")}};r.readAsText(f)}

/* ---- Portfolio / CV ---- */
function portfolio(){return portfolio0()+cvX()}
function portfolio0(){const sc=score();
const sec=(title,rows)=>rows.length?`<div class="card"><h3>${title}</h3>${rows}</div>`:'';
const stg=L('stages').slice().sort((a,b)=>(b.debut||'').localeCompare(a.debut||'')).map(x=>`<div style="margin-bottom:8px"><b>${esc(x.lieu)}</b> <span class="m">${esc(x.debut)} → ${esc(x.fin)}</span>${x.bilan?`<div class="m">${esc(x.bilan)}</div>`:''}</div>`).join('');
const rec=L('recherche').slice().sort((a,b)=>(b.date||'').localeCompare(a.date||'')).map(x=>`<div style="margin-bottom:8px"><b>${esc(x.sujet)}</b> <span class="m">${esc(x.dom)} · ${esc(x.date)}</span>${x.ret?`<div class="m">${esc(x.ret)}</div>`:''}</div>`).join('');
const pub=L('publications').slice().sort((a,b)=>(b.date||'').localeCompare(a.date||'')).map(x=>`<div style="margin-bottom:8px"><b>${esc(x.titre)}</b> <span class="m">${esc(x.type)} · ${esc(x.statut)} · ${esc(x.revue)} · ${esc(x.date)}</span>${x.resume?`<div class="m">${esc(x.resume)}</div>`:''}</div>`).join('');
const pro=L('projets').filter(x=>x.st!='Idée').map(x=>`<div style="margin-bottom:6px"><b>${esc(x.titre)}</b> <span class="m">${esc(x.cat)} · ${esc(x.st)}</span></div>`).join('');
const forma=L('formations').map(x=>`<div style="margin-bottom:6px"><b>${esc(x.titre)}</b> <span class="m">${esc(x.pf)} · ${esc(x.st)} ${x.pr?'('+esc(x.pr)+'%)':''}</span></div>`).join('');
const comp=SK.map((s,i)=>`<div style="margin-bottom:4px"><div class="row"><span>${esc(s[0])}</span><span class="m">${D.comp[i]}/5</span></div>${gauge(D.comp[i]/5)}</div>`).join('');
const nt=notesSum();const pass=L('passerelle').slice().sort((a,b)=>(a.sem||'').localeCompare(b.sem||'')).map(x=>`<div style="margin-bottom:6px"><b>${esc(x.titre)}</b> <span class="m">${esc(x.sem)} · ${esc(x.type)} · ${esc(x.force||'')} · ${esc(x.axe||'')} · ${esc(x.date)}</span>${x.piece?`<div class="m">Justificatif : ${esc(x.piece)}</div>`:''}${x.det?`<div class="m">${esc(x.det)}</div>`:''}</div>`).join('');
return `<div class="card no-print"><button class="btn" onclick="window.print()">🖨 Exporter en PDF</button><p class="m">Le bouton ouvre l'impression du navigateur : choisis « Enregistrer en PDF » comme imprimante.</p></div>
<div id="printarea">
<div class="card"><h3>Naw — Synthèse de progression</h3><p class="m">Nursing school student, IFSI Bichat · Université Paris Cité · Objectif : major de promo → passerelle médecine → recherche</p>${gauge(sc.avg,true)}${sc.parts.map(p=>`<div style="margin-top:6px"><div class="row"><span class="m">${p[0]}</span><span class="m">${Math.round(p[1]*100)}%</span></div>${gauge(p[1])}</div>`).join('')}</div>
${sec('📊 Notes & classement',nt)}
${sec('🩺 Dossier passerelle — preuves',pass)}
${sec('🏥 Stages',stg)}
${sec('🔬 Recherche',rec)}
${sec('📄 Publications & posters',pub)}
${sec('🛠 Projets',pro)}
${sec('🎓 Formations',forma)}
<div class="card"><h3>🧠 Compétences</h3>${comp}</div>
</div>`}

function render(){nav();document.title=(TEST?'[TEST] ':'')+'LIFE-PROJECT — '+LBL(tab);let h='';if(tab=='home')h=home();else if(tab=='comp')h=comp();else if(tab=='plan')h=plan();else if(tab=='portfolio')h=portfolio();else if(tab=='data'){h=data();setTimeout(pinfo,0)}else h=`<h2>${LBL(tab)}</h2>${extra(tab)}${form(tab)}${searchbox(tab)}<div id="list_${tab}">${list(tab)}</div>`;$('#main').innerHTML=h}
stageSyncRun();
render();

/* ---- Sauvegarde & rappels ---- */
function bk(){const t=D._exp||0,w=saveErr?'<div class="card no-print" style="border-color:var(--r)">⚠️ Enregistrement impossible (stockage plein ou bloqué) : exporte tes données maintenant.</div>':'';if(Date.now()-t<6048e5)return w;return w+`<div class="card no-print" style="border-color:var(--o)">⚠️ Sauvegarde .json ${t?'ancienne (> 7 jours)':'jamais faite'}. <button class="btn" onclick="ex()">📤 Exporter maintenant</button></div>`}
function pinfo(){const e=$('#pinfo');if(!e)return;const s=D._saved?new Date(D._saved).toLocaleString('fr-FR'):'—';const p=navigator.storage&&navigator.storage.persisted?navigator.storage.persisted():Promise.resolve(false);p.then(v=>{e.innerHTML='Version '+VER+' · '+(TEST?'<b>environnement TEST (données séparées)</b>':'production')+' · Dernier enregistrement : '+s+' · Stockage protégé : '+(v?'oui ✅':'non (fais des exports)')+' · Dernier export : '+(D._exp?new Date(D._exp).toLocaleDateString('fr-FR'):'jamais')})}
function santeX(){const w=[];for(let i=7;i>=0;i--){const x=add(td(),-7*i-6),y=add(td(),-7*i),e=L('sante').filter(z=>z.date>=x&&z.date<=y),so=e.filter(z=>+z.som>0),en=e.filter(z=>+z.en>0);w.push({s:so.length?so.reduce((t,z)=>t+ +z.som,0)/so.length:null,e:en.length?en.reduce((t,z)=>t+ +z.en,0)/en.length:null})}
const bw=300/8,bars=w.map((z,i)=>`<rect x="${i*bw+6}" y="${70-(z.s||0)*6}" width="${bw/2-6}" height="${(z.s||0)*6}" fill="#2e8b57"/><rect x="${i*bw+bw/2}" y="${70-(z.e||0)*10}" width="${bw/2-6}" height="${(z.e||0)*10}" fill="#d08a1a"/>`).join('');const lowd=L('sante').filter(z=>z.date>=add(td(),-29)&&+z.som>0&&+z.som<6).length;return `<div class="card"><h3>Tendance de récupération · 8 semaines</h3><svg viewBox="0 0 300 76" width="100%">${bars}</svg><p class="m">Vert : sommeil moyen (h) · orange : énergie moyenne (/5). ${lowd} nuit(s) sous 6 h sur 30 jours. Les données viennent de Routine (saisie unique).</p></div>`}
function chart(){const days=[];for(let i=13;i>=0;i--)days.push(add(td(),-i));const v=days.map(d=>{const x=L('sante').find(s=>s.date==d&&s.som);return x?+x.som:0});const w=300/14;return `<div class="card"><h3>Sommeil — 14 jours</h3><svg viewBox="0 0 300 90" width="100%">${v.map((h,i)=>`<rect x="${i*w+2}" y="${80-h*8}" width="${w-4}" height="${h*8}" rx="2" fill="${h>=7?'#2e8b57':h?'#d08a1a':'none'}"/>`).join('')}<line x1="0" x2="300" y1="24" y2="24" stroke="#888" stroke-dasharray="3"/></svg><span class="m">Ligne = 7 h</span></div>`}

/* ---- Persistance durable ---- */
try{if(navigator.storage&&navigator.storage.persist)navigator.storage.persist()}catch(e){}
if(!localStorage.getItem(KEY))idbGet(v=>{if(v){try{D=JSON.parse(v);if(!D.comp)D.comp=SK.map(s=>0);tab=D.tab||'home';render()}catch(e){}}});
document.addEventListener('visibilitychange',()=>{if(document.hidden)save()});
window.addEventListener('pagehide',save);
if('serviceWorker' in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});

if(TEST){const b=document.createElement('div');b.id='tstb';b.textContent='TEST · données séparées';document.body.appendChild(b)}
